1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: grid;
13	    place-items: center;
14	    background: #eef0f3;
15	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
16	  }
17	  .calc {
18	    width: min(320px, 100vw - 32px);
19	    padding: 16px;
20	    border-radius: 20px;
21	    background: #1f2329;
22	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
23	  }
24	  .screen { position: relative; margin-bottom: 16px; }
25	  .mem-indicator { position: absolute; top: 8px; left: 12px; color: #8ab4ff; font-size: 13px; opacity: 0.2; }
26	  .mem-indicator[data-active="true"] { opacity: 1; }
27	  .display {
28	    height: 80px;
29	    padding: 0 12px;
30	    border-radius: 12px;
31	    background: #111418;
32	    color: #fff;
33	    font-size: 40px;
34	    display: flex;
35	    align-items: center;
36	    justify-content: flex-end;
37	    overflow: hidden;
38	    white-space: nowrap;
39	    font-variant-numeric: tabular-nums;
40	  }
41	  .keys {
42	    display: grid;
43	    grid-template-columns: repeat(4, 1fr);
44	    gap: 10px;
45	  }
46	  button {
47	    height: 60px;
48	    border: 0;
49	    border-radius: 12px;
50	    background: #3a4049;
51	    color: #fff;
52	    font: inherit;
53	    font-size: 22px;
54	    cursor: pointer;
55	  }
56	  button:hover { filter: brightness(1.15); }
57	  button:active { filter: brightness(0.9); }
58	  button:focus-visible { outline: 2px solid #8ab4ff; outline-offset: 2px; }
59	  .op { background: #f08c2e; }
60	  .op.active { background: #fff; color: #f08c2e; }
61	  .fn { background: #8a929c; color: #111; }
62	  .wide { grid-column: span 2; }
63	  .mem { height: 44px; background: #2b3037; font-size: 16px; }
64	  .tape { margin-top: 16px; padding-top: 12px; border-top: 1px solid #3a4049; color: #fff; }
65	  .tape-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; color: #8a929c; font-size: 13px; }
66	  .tape-clear { height: auto; padding: 4px 10px; border-radius: 8px; background: transparent; color: #8ab4ff; font-size: 13px; }
67	  .tape-rows { list-style: none; margin: 0; padding: 0; max-height: 180px; overflow-y: auto; }
68	  .tape-row { display: flex; flex-direction: column; align-items: flex-end; padding: 6px 12px; font-variant-numeric: tabular-nums; }
69	  .tape-row + .tape-row { border-top: 1px solid #2b3037; }
70	  .tape-expr { color: #8a929c; font-size: 14px; overflow-wrap: anywhere; text-align: right; }
71	  .tape-result { font-size: 20px; }
72	</style>
73	</head>
74	<body>
75	<main class="calc">
76	  <div class="screen">
77	    <span class="mem-indicator" data-testid="mem-indicator" data-active="false" aria-label="memory">M</span>
78	    <div class="display" data-testid="calc-display" data-value="0" data-error="false" role="status" aria-live="polite">0</div>
79	  </div>
80	  <div class="keys">
81	    <button class="mem" data-testid="key-mc" data-key="mc" aria-label="memory clear">MC</button>
82	    <button class="mem" data-testid="key-mr" data-key="mr" aria-label="memory recall">MR</button>
83	    <button class="mem wide" data-testid="key-mplus" data-key="mplus" aria-label="memory add">M+</button>
84	    <button class="fn wide" data-testid="key-lparen" data-key="lparen" aria-label="open group">(</button>
85	    <button class="fn wide" data-testid="key-rparen" data-key="rparen" aria-label="close group">)</button>
86	    <button class="fn wide" data-testid="key-clear" data-key="clear">AC</button>
87	    <button class="fn" data-testid="key-sign" data-key="sign" aria-label="change sign">±</button>
88	    <button class="op" data-testid="key-div" data-key="div" aria-label="divide">÷</button>
89	    <button data-testid="key-7" data-key="7">7</button>
90	    <button data-testid="key-8" data-key="8">8</button>
91	    <button data-testid="key-9" data-key="9">9</button>
92	    <button class="op" data-testid="key-mul" data-key="mul" aria-label="multiply">×</button>
93	    <button class="op" data-testid="key-sub" data-key="sub" aria-label="subtract">−</button>
94	    <button data-testid="key-4" data-key="4">4</button>
95	    <button data-testid="key-5" data-key="5">5</button>
96	    <button data-testid="key-6" data-key="6">6</button>
97	    <button class="op" data-testid="key-add" data-key="add" aria-label="add">+</button>
98	    <button data-testid="key-1" data-key="1">1</button>
99	    <button data-testid="key-2" data-key="2">2</button>
100	    <button data-testid="key-3" data-key="3">3</button>
101	    <button class="wide" data-testid="key-0" data-key="0">0</button>
102	    <button data-testid="key-dot" data-key="dot" aria-label="decimal point">.</button>
103	    <button class="op" data-testid="key-equals" data-key="equals" aria-label="equals">=</button>
104	  </div>
105	  <section class="tape" data-testid="calc-tape" aria-label="History">
106	    <div class="tape-head">
107	      <span>History</span>
108	      <button class="tape-clear" data-testid="tape-clear">Clear</button>
109	    </div>
110	    <ol class="tape-rows"></ol>
111	  </section>
112	</main>
113	<script>
114	// Pure calculator logic. State: acc (stored left operand), op (pending operator),
115	// entry (digits being typed, or null), value (the current number, never rounded),
116	// error (true after a division by zero; only clear leaves it), stack (saved acc/op of each
117	// open group), closed (true right after `)`, MR, or M+ on an entry: value is finished, not an entry).
118	var OPS = {
119	  add: function (a, b) { return a + b; },
120	  sub: function (a, b) { return a - b; },
121	  mul: function (a, b) { return a * b; },
122	  div: function (a, b) { return a / b; }
123	};
124	
125	function initialState() {
126	  return { acc: null, op: null, entry: null, value: 0, error: false, stack: [], closed: false };
127	}
128	
129	function errorState(v) {
130	  return { acc: null, op: null, entry: null, value: v, error: true, stack: [], closed: false };
131	}
132	
133	function press(s, key) {
134	  if (key === 'clear') return initialState();
135	
136	  // In the error state every key except clear is ignored.
137	  if (s.error) return s;
138	
139	  if (/^[0-9]$/.test(key)) {
140	    var entry = s.entry === null || s.entry === '0' ? key : s.entry === '-0' ? '-' + key : s.entry + key;
141	    return { acc: s.acc, op: s.op, entry: entry, value: Number(entry), error: false, stack: s.stack, closed: false };
142	  }
143	
144	  if (key === 'dot') {
145	    var e = s.entry === null ? '0' : s.entry;
146	    if (e.indexOf('.') !== -1) return s;
147	    e += '.';
148	    return { acc: s.acc, op: s.op, entry: e, value: Number(e), error: false, stack: s.stack, closed: false };
149	  }
150	
151	  // Sign and percent act on the current entry. Right after an operator there is no
152	  // entry yet, so they start one from 0. After a result or a closed group they act on the value.
153	  if (key === 'sign' || key === 'percent') {
154	    if (s.entry === null && (!s.op || s.closed)) {
155	      var nv = key === 'sign' ? -s.value : s.value / 100;
156	      return { acc: s.acc, op: s.op, entry: null, value: nv, error: false, stack: s.stack, closed: s.closed };
157	    }
158	    var cur = s.entry === null ? '0' : s.entry;
159	    var ne = key === 'sign' ? (cur[0] === '-' ? cur.slice(1) : '-' + cur) : shiftDecimal(cur, -2);
160	    return { acc: s.acc, op: s.op, entry: ne, value: Number(ne), error: false, stack: s.stack, closed: false };
161	  }
162	
163	  if (key in OPS) {
164	    // Operator right after another operator replaces it.
165	    if (s.op && s.entry === null && !s.closed) return { acc: s.acc, op: key, entry: null, value: s.value, error: false, stack: s.stack, closed: false };
166	    // Immediate execution: finish the waiting operation first, strictly left to right,
167	    // no precedence. The display always shows a real running result.
168	    var v = s.op ? OPS[s.op](s.acc, s.value) : s.value;
169	    if (!isFinite(v)) return errorState(v);
170	    return { acc: v, op: key, entry: null, value: v, error: false, stack: s.stack, closed: false };
171	  }
172	
173	  // `(` saves the waiting operation and starts a fresh one inside the group. It only
174	  // makes sense where a number could start, so it is ignored after an entry or a group.
175	  if (key === 'lparen') {
176	    if (s.entry !== null || s.closed) return s;
177	    var frame = { acc: s.acc, op: s.op };
178	    return { acc: null, op: null, entry: null, value: 0, error: false, stack: s.stack.concat([frame]), closed: false };
179	  }
180	
181	  // `)` finishes the group like equals, then restores the saved operation with the group
182	  // result as its right operand. Without an open group it is ignored.
183	  if (key === 'rparen') {
184	    if (!s.stack.length) return s;
185	    var g = s.op ? OPS[s.op](s.acc, s.value) : s.value;
186	    if (!isFinite(g)) return errorState(g);
187	    var top = s.stack[s.stack.length - 1];
188	    return { acc: top.acc, op: top.op, entry: null, value: g, error: false, stack: s.stack.slice(0, -1), closed: true };
189	  }
190	
191	  if (key === 'equals') {
192	    // Equals closes any groups left open.
193	    while (s.stack.length) {
194	      s = press(s, 'rparen');
195	      if (s.error) return s;
196	    }
197	    if (!s.op) return { acc: null, op: null, entry: null, value: s.value, error: false, stack: [], closed: false };
198	    var r = OPS[s.op](s.acc, s.value);
199	    if (!isFinite(r)) return errorState(r);
200	    return { acc: null, op: null, entry: null, value: r, error: false, stack: [], closed: false };
201	  }
202	
203	  return s;
204	}
205	
206	// Memory keys. Memory lives beside the state, so clear leaves it; it starts at 0 and, like
207	// value, is never rounded. In the error state they are ignored, like every key but clear.
208	function pressMemory(s, mem, key) {
209	  if (s.error) return { state: s, mem: mem };
210	  if (key === 'mc') return { state: s, mem: 0 };
211	  // MR puts memory in as a finished value: the next digit starts a new entry and an
212	  // operator uses it as its operand.
213	  if (key === 'mr') {
214	    return { state: { acc: s.acc, op: s.op, entry: null, value: mem, error: false, stack: s.stack, closed: true }, mem: mem };
215	  }
216	  // M+ adds the current value and ends a typed entry the same way.
217	  var m = mem + s.value;
218	  if (!isFinite(m)) return { state: errorState(m), mem: mem };
219	  if (s.entry === null) return { state: s, mem: m };
220	  return { state: { acc: s.acc, op: s.op, entry: null, value: s.value, error: false, stack: s.stack, closed: true }, mem: m };
221	}
222	
223	// Moves the decimal point of an entry string by n places, exactly, with no float noise.
224	// shiftDecimal('50', -2) is '0.5'.
225	function shiftDecimal(entry, n) {
226	  var sign = entry[0] === '-' ? '-' : '';
227	  var parts = entry.slice(sign.length).split('.');
228	  var digits = parts[0] + (parts[1] || '');
229	  var pos = parts[0].length + n;
230	  var str = pos <= 0 ? '0.' + '0'.repeat(-pos) + digits
231	    : pos >= digits.length ? digits + '0'.repeat(pos - digits.length)
232	    : digits.slice(0, pos) + '.' + digits.slice(pos);
233	  if (str.indexOf('.') !== -1) str = str.replace(/0+$/, '').replace(/\.$/, '');
234	  str = str.replace(/^0+(?=\d)/, '');
235	  return sign + str;
236	}
237	
238	// Presentation only: at most 10 significant digits, no trailing zeros, no separators.
239	// Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
240	function formatNumber(x) {
241	  var m = Math.abs(x).toExponential(9).split('e');
242	  var digits = m[0].replace('.', '');
243	  var exp = Number(m[1]);
244	  var sign = x < 0 ? '-' : '';
245	  if (x !== 0 && (exp >= 10 || exp < -9)) {
246	    return sign + m[0].replace(/\.?0+$/, '') + 'e' + m[1];
247	  }
248	  var int = exp >= 0 ? digits.slice(0, exp + 1) : '0';
249	  var frac = (exp >= 0 ? digits.slice(exp + 1) : '0'.repeat(-exp - 1) + digits).replace(/0+$/, '');
250	  return (int === '0' && frac === '' ? '' : sign) + int + (frac ? '.' + frac : '');
251	}
252	
253	// Visible text: the entry exactly as typed, Error, or the value formatted at render time.
254	function displayText(s) {
255	  if (s.error) return 'Error';
256	  if (s.entry !== null) return s.entry;
257	  return formatNumber(s.value);
258	}
259	
260	// Expression for the tape, tracked beside press(): head (tokens before the current operand),
261	// operand (text of a finished group or a changed group, or null to use the entry or value),
262	// groups (heads saved by each open `(`).
263	var SYMBOLS = { add: '+', sub: '−', mul: '×', div: '÷' };
264	
265	function initialExpr() {
266	  return { head: [], operand: null, groups: [] };
267	}
268	
269	function operandText(s, t) {
270	  if (s.entry !== null) return s.entry.replace(/\.$/, '');
271	  if (t.operand !== null) return t.operand;
272	  return formatNumber(s.value);
273	}
274	
275	// Returns the expression after key moved state s to n, and the tape row
276	// ({ expr, value }) when equals completed a calculation.
277	function trackExpr(t, s, key, n) {
278	  if (key === 'clear' || n.error) return { expr: initialExpr(), row: null };
279	  if (n === s) return { expr: t, row: null };
280	  if (key === 'mr') return { expr: { head: t.head, operand: null, groups: t.groups }, row: null };
281	  if (/^[0-9]$/.test(key) || key === 'dot') {
282	    return { expr: { head: t.head, operand: null, groups: t.groups }, row: null };
283	  }
284	  if (key === 'sign' || key === 'percent') {
285	    var o = null;
286	    if (s.entry === null && (!s.op || s.closed) && t.operand !== null) {
287	      o = key === 'percent' ? t.operand + '%' : t.operand[0] === '-' ? t.operand.slice(1) : '-' + t.operand;
288	    }
289	    return { expr: { head: t.head, operand: o, groups: t.groups }, row: null };
290	  }
291	  if (key in OPS) {
292	    var head = s.op && s.entry === null && !s.closed
293	      ? t.head.slice(0, -1).concat([SYMBOLS[key]])
294	      : t.head.concat([operandText(s, t), SYMBOLS[key]]);
295	    return { expr: { head: head, operand: null, groups: t.groups }, row: null };
296	  }
297	  if (key === 'lparen') {
298	    return { expr: { head: [], operand: null, groups: t.groups.concat([t.head]) }, row: null };
299	  }
300	  if (key === 'rparen') {
301	    var group = '(' + t.head.concat([operandText(s, t)]).join(' ') + ')';
302	    return { expr: { head: t.groups[t.groups.length - 1], operand: group, groups: t.groups.slice(0, -1) }, row: null };
303	  }
304	  if (key === 'equals') {
305	    // A bare number is not a calculation, so it adds no row.
306	    var calc = t.head.length || t.groups.length || t.operand !== null;
307	    while (s.stack.length) {
308	      var next = press(s, 'rparen');
309	      t = trackExpr(t, s, 'rparen', next).expr;
310	      s = next;
311	    }
312	    var row = calc ? { expr: t.head.concat([operandText(s, t)]).join(' '), value: n.value } : null;
313	    return { expr: initialExpr(), row: row };
314	  }
315	  return { expr: t, row: null };
316	}
317	
318	if (typeof document !== 'undefined') {
319	  var state = initialState();
320	  var expr = initialExpr();
321	  var tape = [];
322	  var memory = 0;
323	  var memIndicator = document.querySelector('[data-testid="mem-indicator"]');
324	  var tapeRows = document.querySelector('.tape-rows');
325	  var display = document.querySelector('[data-testid="calc-display"]');
326	  var opButtons = document.querySelectorAll('[data-key="add"],[data-key="sub"],[data-key="mul"],[data-key="div"]');
327	
328	  function render() {
329	    display.textContent = displayText(state);
330	    display.setAttribute('data-value', String(state.value));
331	    display.setAttribute('data-error', state.error ? 'true' : 'false');
332	    memIndicator.setAttribute('data-active', memory !== 0 ? 'true' : 'false');
333	    for (var i = 0; i < opButtons.length; i++) {
334	      var b = opButtons[i];
335	      b.classList.toggle('active', state.op === b.dataset.key && state.entry === null && !state.closed);
336	    }
337	  }
338	
339	  function renderTape() {
340	    tapeRows.textContent = '';
341	    for (var i = 0; i < tape.length; i++) {
342	      var li = document.createElement('li');
343	      li.className = 'tape-row';
344	      li.setAttribute('data-testid', 'tape-row');
345	      var ex = document.createElement('span');
346	      ex.className = 'tape-expr';
347	      ex.setAttribute('data-testid', 'tape-expr');
348	      ex.textContent = tape[i].expr;
349	      var res = document.createElement('span');
350	      res.className = 'tape-result';
351	      res.setAttribute('data-testid', 'tape-result');
352	      res.setAttribute('data-value', String(tape[i].value));
353	      res.textContent = formatNumber(tape[i].value);
354	      li.appendChild(ex);
355	      li.appendChild(res);
356	      tapeRows.appendChild(li);
357	    }
358	  }
359	
360	  function apply(key) {
361	    var next;
362	    if (key === 'mc' || key === 'mr' || key === 'mplus') {
363	      var m = pressMemory(state, memory, key);
364	      next = m.state;
365	      memory = m.mem;
366	    } else {
367	      next = press(state, key);
368	    }
369	    var r = trackExpr(expr, state, key, next);
370	    state = next;
371	    expr = r.expr;
372	    if (r.row) {
373	      tape.unshift(r.row);
374	      renderTape();
375	    }
376	    render();
377	  }
378	
379	  document.querySelector('.keys').addEventListener('click', function (ev) {
380	    var btn = ev.target.closest('button');
381	    if (!btn) return;
382	    apply(btn.dataset.key);
383	  });
384	
385	  // Clearing the tape leaves the calculator and its display untouched.
386	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
387	    tape = [];
388	    renderTape();
389	  });
390	
391	  var KEYMAP = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul', '/': 'div',
392	    '(': 'lparen', ')': 'rparen', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
393	  document.addEventListener('keydown', function (ev) {
394	    var key = /^[0-9]$/.test(ev.key) ? ev.key : KEYMAP[ev.key];
395	    if (!key || ev.ctrlKey || ev.metaKey || ev.altKey) return;
396	    ev.preventDefault();
397	    apply(key);
398	  });
399	
400	  render();
401	}
402	</script>
403	</body>
404	</html>
